@Threads(1)
@State(Scope.Thread)
public class ObservableMapOptionalBenchmark {

    @Param({ "1000", "10000", "100000" })
    public int size;

    private Observable<Integer> source;

    // Use a wildcard on the Optional to match the constructor signature.
    private Function<Integer, Optional<? extends Integer>> mapper;

    @Setup(Level.Trial)
    public void setUp() {
        source = Observable.range(1, size);
        mapper = i -> (i & 1) == 0 ? Optional.of(i) : Optional.empty();
