import io.reactivex.rxjava3.plugins.*;
import io.reactivex.rxjava3.processors.*;
import io.reactivex.rxjava3.schedulers.*;
import io.reactivex.rxjava3.subjects.*;
import io.reactivex.rxjava3.subscribers.*;
import org.openjdk.jmh.annotations.*;
import org.openjdk.jmh.infra.*;

/**
 * Throughput benchmark for {@code ParallelCollector}.
 *
 * The benchmark creates a {@link Flowable} of integers, turns it into a {@link ParallelFlowable},
 * applies the internal {@code ParallelCollector} via the public {@code collect} operator and blocks
 * for the final result. The throughput (operations per second) is measured.
 */
@BenchmarkMode(Mode.Throughput)
@OutputTimeUnit(TimeUnit.SECONDS)
@Warmup(iterations = 5, time = 1, timeUnit = TimeUnit.SECONDS)
@Measurement(iterations = 10, time = 1, timeUnit = TimeUnit.SECONDS)
@Fork(2)
@State(Scope.Benchmark)
public class ParallelCollectorBenchmark {

    @Param({ "1000", "10000", "100000" })
    public int itemCount;

    @Param({ "1", "2", "4", "8" })
    public int parallelism;

    private ParallelFlowable<Integer> source;

    private Collector<Integer, ?, Integer> collector;

    @Setup(Level.Trial)
    public void setUp() {
        // Create a range Flowable, parallelise it and run on computation scheduler.
        source = Flowable.range(1, itemCount).parallel(parallelism).runOn(Schedulers.computation());
        // Simple summing collector; any collector can be used.
        collector = Collectors.summingInt(i -> i);
    }

    @Benchmark
    public void parallelCollect(Blackhole bh) {
        // Apply the ParallelCollector via the public API and block for the result.
        int result = source.collect(collector).blockingFirst();
        bh.consume(result);
    }
}

