                    if (q == null || q.isEmpty()) {

                        emitted = e + 1;
                        downstream.onNext(t);

                        int c = consumed + 1;
                        if (c == limit) {
                            consumed = 0;
                            mainSubscription.get().request(c);
                        } else {
                            consumed = c;
                        }
