        // intentionally empty – drop handling is not part of the throughput measurement
    };

    @Setup(Level.Trial)
    public void setup() {
        // Use a computation scheduler to decouple emission from the benchmark thread.
        source = Flowable.range(1, itemCount).subscribeOn(Schedulers.computation()).// hide to prevent fusion optimizations that would bypass the operator
        hide();
    }

