import io.reactivex.rxjava3.plugins.*;
import io.reactivex.rxjava3.processors.*;
import io.reactivex.rxjava3.schedulers.*;
import io.reactivex.rxjava3.subjects.*;
import io.reactivex.rxjava3.subscribers.*;
import org.openjdk.jmh.annotations.*;
import org.openjdk.jmh.infra.*;

/**
 * Benchmark for {@code Flowable.onBackpressureReduceWith} operator.
 *
 * <p>Measures the throughput (operations per second) of reducing a stream of integers
 * using a supplied initial value and a reducer function. The benchmark is designed
 * to reflect realistic usage patterns while avoiding common pitfalls:
 *
 * <ul>
 *   <li>Uses {@code blockingSubscribe} to ensure the whole flow is executed within the benchmark iteration.</li>
 *   <li>Parameters allow varying the size of the source sequence to observe scaling behavior.</li>
 *   <li>All objects are created in {@link #setup()} to exclude allocation overhead from the measured section.</li>
 *   <li>Uses {@link Blackhole} to consume the final reduced values, preventing dead‑code elimination.</li>
 * </ul>
 */
@BenchmarkMode(Mode.Throughput)
@OutputTimeUnit(TimeUnit.SECONDS)
@Warmup(iterations = 5, time = 1, timeUnit = TimeUnit.SECONDS)
@Measurement(iterations = 10, time = 1, timeUnit = TimeUnit.SECONDS)
@Fork(value = 2)
@State(Scope.Thread)
public class FlowableOnBackpressureReduceWithBenchmark {

    /**
     * Number of items emitted by the source Flowable.
     * Typical values: 1_000, 10_000, 100_000.
     */
    @Param({ "1000", "10000", "100000" })
    public int size;

    private Flowable<Integer> flowable;

    private Supplier<Integer> supplier;

    private BiFunction<Integer, Integer, Integer> reducer;

    @Setup(Level.Trial)
    public void setup() {
        // Source emitting a range of integers [1 .. size]
        Flowable<Integer> source = Flowable.range(1, size);
        // Simple sum reduction: start from 0 and add each element
        supplier = () -> 0;
        reducer = (sum, value) -> sum + value;
        // Apply the operator under test using the internal class directly
        flowable = new FlowableOnBackpressureReduceWith<>(source, supplier, reducer);
    }

    /**
     * Executes the whole flow and consumes the final reduced value.
     *
     * @param bh Blackhole to consume the result and avoid dead‑code elimination.
     */
    @Benchmark
    public void reduceWith(Blackhole bh) {
        // blockingSubscribe ensures the flow runs to completion within the benchmark iteration.
        flowable.blockingSubscribe(bh::consume);
    }
}

