import io.reactivex.rxjava3.internal.operators.maybe.*;
import io.reactivex.rxjava3.internal.operators.mixed.*;
import io.reactivex.rxjava3.internal.operators.observable.*;
import io.reactivex.rxjava3.internal.operators.parallel.*;
import io.reactivex.rxjava3.internal.operators.single.*;
import io.reactivex.rxjava3.internal.queue.*;
import io.reactivex.rxjava3.internal.schedulers.*;
import io.reactivex.rxjava3.internal.subscribers.*;
import io.reactivex.rxjava3.internal.subscriptions.*;
import io.reactivex.rxjava3.internal.util.*;
import io.reactivex.rxjava3.observables.*;
import io.reactivex.rxjava3.observers.*;
import io.reactivex.rxjava3.operators.*;
import io.reactivex.rxjava3.parallel.*;
import io.reactivex.rxjava3.plugins.*;
import io.reactivex.rxjava3.processors.*;
import io.reactivex.rxjava3.schedulers.*;
import io.reactivex.rxjava3.subjects.*;
import io.reactivex.rxjava3.subscribers.*;
import org.openjdk.jmh.annotations.*;
import org.openjdk.jmh.infra.*;

/**
 * JMH benchmark for {@link io.reactivex.rxjava3.internal.operators.flowable.FlowableScanSeed}.
 * Measures the throughput of the scan operator with a seed value.
 */
@BenchmarkMode(Mode.Throughput)
@OutputTimeUnit(TimeUnit.SECONDS)
@Warmup(iterations = 5, time = 1, timeUnit = TimeUnit.SECONDS)
@Measurement(iterations = 10, time = 1, timeUnit = TimeUnit.SECONDS)
@Fork(2)
@State(Scope.Thread)
public class FlowableScanSeedBenchmark {

    /**
     * Number of items emitted by the source Flowable.
     */
    @Param({ "1000", "10000", "100000" })
    public int itemCount;

    /**
     * Source Flowable emitting a range of integers.
     */
    private Flowable<Integer> source;

    /**
     * Scan operator under test.
     */
    private Flowable<Integer> scanned;

    /**
     * Seed supplier returning the initial accumulator value.
     */
    private Supplier<Integer> seedSupplier = () -> 0;

    /**
     * Accumulator function adding the incoming value to the current sum.
     */
    private BiFunction<Integer, Integer, Integer> accumulator = (sum, value) -> sum + value;

    @Setup(Level.Trial)
    public void setUp() {
        // Create a cold source that emits a deterministic range of integers.
        source = Flowable.range(1, itemCount);
        // Apply the scan operator with a seed. hide() prevents operator fusion
        // which could otherwise mask the true cost of the ScanSeed implementation.
        scanned = source.scanWith(seedSupplier, accumulator).hide();
    }

    /**
     * Consumes the entire sequence produced by the scan operator.
     * The Blackhole ensures that the consumed values are not optimized away.
     */
    @Benchmark
    public void scanSeed(Blackhole bh) {
        scanned.blockingForEach(bh::consume);
    }
}

