package io.reactivex.rxjava3.internal.operators.flowable;

import java.util.concurrent.TimeUnit;
import io.reactivex.rxjava3.annotations.*;
import io.reactivex.rxjava3.core.*;
import io.reactivex.rxjava3.disposables.*;
import io.reactivex.rxjava3.exceptions.*;
import io.reactivex.rxjava3.flowables.*;
import io.reactivex.rxjava3.functions.*;
import io.reactivex.rxjava3.internal.disposables.*;
import io.reactivex.rxjava3.internal.functions.*;
import io.reactivex.rxjava3.internal.fuseable.*;
import io.reactivex.rxjava3.internal.jdk8.*;
import io.reactivex.rxjava3.internal.observers.*;
import io.reactivex.rxjava3.internal.operators.completable.*;
import io.reactivex.rxjava3.internal.operators.maybe.*;
import io.reactivex.rxjava3.internal.operators.mixed.*;
import io.reactivex.rxjava3.internal.operators.observable.*;
import io.reactivex.rxjava3.internal.operators.parallel.*;
import io.reactivex.rxjava3.internal.operators.single.*;
import io.reactivex.rxjava3.internal.queue.*;
import io.reactivex.rxjava3.internal.schedulers.*;
import io.reactivex.rxjava3.internal.subscribers.*;
import io.reactivex.rxjava3.internal.subscriptions.*;
import io.reactivex.rxjava3.internal.util.*;
import io.reactivex.rxjava3.observables.*;
import io.reactivex.rxjava3.observers.*;
import io.reactivex.rxjava3.operators.*;
import io.reactivex.rxjava3.parallel.*;
import io.reactivex.rxjava3.plugins.*;
import io.reactivex.rxjava3.processors.*;
import io.reactivex.rxjava3.schedulers.*;
import io.reactivex.rxjava3.subjects.*;
import io.reactivex.rxjava3.subscribers.*;
import org.openjdk.jmh.annotations.*;
import org.openjdk.jmh.infra.*;

/**
 * JMH benchmark for {@link io.reactivex.rxjava3.internal.operators.flowable.FlowableSequenceEqual}.
 *
 * The benchmark measures the throughput (operations per second) of the
 * {@code Flowable.sequenceEqual} operator under different sequence sizes and
 * prefetch values. It uses {@link Flowable#range} as a deterministic source
 * and a simple {@code Objects::equals} comparator.
 *
 * Best practices applied:
 * - {@code @State(Scope.Thread)} isolates benchmark state per thread.
 * - Parameters are provided for sequence size and prefetch to explore scaling.
 * - {@code @Setup(Level.Iteration)} prepares fresh sources for each iteration,
 *   avoiding cross‑iteration interference.
 * - The result is consumed via {@link Blackhole} to prevent dead‑code elimination.
 * - Warm‑up and measurement iterations are defined to let the JVM reach a steady state.
 */
@BenchmarkMode(Mode.Throughput)
@OutputTimeUnit(TimeUnit.SECONDS)
@Warmup(iterations = 5, time = 1, timeUnit = TimeUnit.SECONDS)
@Measurement(iterations = 10, time = 1, timeUnit = TimeUnit.SECONDS)
@Fork(value = 2, jvmArgsAppend = { "-XX:+UnlockDiagnosticVMOptions", "-XX:+PrintCompilation" })
@State(Scope.Thread)
public class FlowableSequenceEqualBenchmark {

    /**
     * Number of items emitted by each source Flowable.
     */
    @Param({ "10", "100", "1000", "10000" })
    public int size;

    /**
     * Prefetch size used by the operator.
     */
    @Param({ "32", "128", "512" })
    public int prefetch;

    private Flowable<Integer> source1;

    private Flowable<Integer> source2;

    private BiPredicate<Integer, Integer> comparer;

    @Setup(Level.Iteration)
    public void setUp() {
        // Deterministic sources emitting the same sequence of integers.
        source1 = Flowable.range(1, size);
        source2 = Flowable.range(1, size);
        // Simple equality comparator.
        comparer = Integer::equals;
    }

    /**
     * Executes the sequenceEqual operator and consumes the Boolean result.
     *
     * @param bh Blackhole to consume the result and avoid dead‑code elimination.
     */
    @Benchmark
    public void sequenceEqualThroughput(Blackhole bh) {
        // The operator under test. The prefetch parameter is passed directly.
        Boolean equal = Flowable.sequenceEqual(source1, source2, comparer, prefetch).blockingGet();
        // Consume the result so the JIT cannot eliminate the whole pipeline.
        bh.consume(equal);
    }

    @TearDown(Level.Iteration)
    public void tearDown() {
        source1 = null;
        source2 = null;
        comparer = null;
    }
}

