import io.reactivex.rxjava3.observers.*;
import io.reactivex.rxjava3.operators.*;
import io.reactivex.rxjava3.parallel.*;
import io.reactivex.rxjava3.plugins.*;
import io.reactivex.rxjava3.processors.*;
import io.reactivex.rxjava3.schedulers.*;
import io.reactivex.rxjava3.subjects.*;
import io.reactivex.rxjava3.subscribers.*;
import org.openjdk.jmh.annotations.*;
import org.openjdk.jmh.infra.*;

/**
 * JMH benchmarks for {@link FlowableSingleMaybe}.
 *
 * <p>Measures the throughput of the operator in three typical scenarios:
 * <ul>
 *   <li>Single element source (expected success)</li>
 *   <li>Empty source (expected completion)</li>
 *   <li>Multiple elements source (expected error)</li>
 * </ul>
 *
 * <p>Best‑practice JMH settings are used:
 * <ul>
 *   <li>Warm‑up iterations to let the JIT stabilize</li>
 *   <li>Multiple measurement iterations for statistical confidence</li>
 *   <li>Forks to isolate JVM state</li>
 *   <li>Blackhole consumption to prevent dead‑code elimination</li>
 * </ul>
 */
@BenchmarkMode(Mode.Throughput)
@OutputTimeUnit(TimeUnit.SECONDS)
@Warmup(iterations = 5, time = 1, timeUnit = TimeUnit.SECONDS)
@Measurement(iterations = 10, time = 1, timeUnit = TimeUnit.SECONDS)
@Fork(value = 2)
@State(Scope.Thread)
public class FlowableSingleMaybeBenchmark {

    /**
     * Maybe that wraps a Flowable emitting exactly one element.
     */
    private Maybe<Integer> singleElementMaybe;

    /**
     * Maybe that wraps an empty Flowable.
     */
    private Maybe<Integer> emptyMaybe;

    /**
     * Maybe that wraps a Flowable emitting more than one element (will error).
     */
    private Maybe<Integer> multipleElementsMaybe;

    @Setup(Level.Trial)
    public void setUp() {
        Flowable<Integer> single = Flowable.just(42);
        Flowable<Integer> empty = Flowable.empty();
        Flowable<Integer> multiple = Flowable.fromArray(1, 2, 3);
        singleElementMaybe = new FlowableSingleMaybe<>(single);
        emptyMaybe = new FlowableSingleMaybe<>(empty);
        multipleElementsMaybe = new FlowableSingleMaybe<>(multiple);
    }

    @Benchmark
    public void singleElement(Blackhole bh) {
        // blockingGet() returns the value or throws; we consume the result with Blackhole.
        try {
            Integer v = singleElementMaybe.blockingGet();
            bh.consume(v);
        } catch (Throwable t) {
            // Should not happen for the single‑element case.
            bh.consume(t);
        }
    }

    @Benchmark
    public void empty(Blackhole bh) {
        // For an empty source, blockingGet() returns null.
        try {
            Integer v = emptyMaybe.blockingGet();
            bh.consume(v);
        } catch (Throwable t) {
            bh.consume(t);
        }
    }

    @Benchmark
    public void multipleElements(Blackhole bh) {
        // The operator should signal IllegalArgumentException.
        try {
            multipleElementsMaybe.blockingGet();
            // If no exception, consume a sentinel to avoid dead code elimination.
            bh.consume("no-error");
        } catch (IllegalArgumentException expected) {
            bh.consume(expected);
        } catch (Throwable t) {
            // Any other unexpected throwable is also consumed.
            bh.consume(t);
        }
    }
}

