/**
 * Benchmark for {@link io.reactivex.rxjava3.internal.operators.flowable.FlowableSkip}.
 * Measures the throughput of the skip operator under different skip counts and source sizes.
 */
@BenchmarkMode(Mode.Throughput)
@OutputTimeUnit(TimeUnit.SECONDS)
@Warmup(iterations = 5, time = 1, timeUnit = TimeUnit.SECONDS)
@Measurement(iterations = 5, time = 1, timeUnit = TimeUnit.SECONDS)
@Fork(1)
@State(Scope.Thread)
public class FlowableSkipBenchmark {

    /**
     * Number of items to skip. Typical values cover edge cases (0, 1) and larger skips.
     */
    @Param({ "0", "1", "10", "100", "1000" })
    public long skipCount;

    /**
     * Total number of items emitted by the source Flowable.
     */
    @Param({ "1000", "10000", "100000" })
    public int sourceSize;

    private Flowable<Integer> source;

    @Setup(Level.Trial)
    public void setUp() {
        // Flowable.range creates a cold source; each subscription will get a fresh sequence.
        source = Flowable.range(1, sourceSize);
    }

    /**
     * Executes the skip operator and consumes all resulting items.
     *
     * @param bh Blackhole to consume items and prevent dead-code elimination.
     */
    @Benchmark
    public void skipAndConsume(Blackhole bh) {
        // The blockingForEach call ensures the whole stream is processed before the benchmark method returns.
        source.skip(skipCount).blockingForEach(bh::consume);
    }
}

