import io.reactivex.rxjava3.internal.subscriptions.*;
import io.reactivex.rxjava3.internal.util.*;
import io.reactivex.rxjava3.observables.*;
import io.reactivex.rxjava3.observers.*;
import io.reactivex.rxjava3.operators.*;
import io.reactivex.rxjava3.parallel.*;
import io.reactivex.rxjava3.plugins.*;
import io.reactivex.rxjava3.processors.*;
import io.reactivex.rxjava3.schedulers.*;
import io.reactivex.rxjava3.subjects.*;
import io.reactivex.rxjava3.subscribers.*;
import org.openjdk.jmh.annotations.*;
import org.openjdk.jmh.infra.*;

/**
 * JMH benchmark for {@link FlowableWithLatestFromMany}.
 *
 * Measures the throughput (operations per second) of the operator when combining a source
 * {@link Flowable} with a configurable number of other publishers.
 *
 * The benchmark runs synchronously (no asynchronous schedulers) to focus on the operator's
 * internal overhead. The combiner simply creates an {@code Object[]} and returns the first
 * element to avoid extra computation that could mask the operator's cost.
 */
@BenchmarkMode(Mode.Throughput)
@OutputTimeUnit(TimeUnit.SECONDS)
@Warmup(iterations = 5, time = 1, timeUnit = TimeUnit.SECONDS)
@Measurement(iterations = 5, time = 1, timeUnit = TimeUnit.SECONDS)
@Fork(1)
@State(Scope.Thread)
public class FlowableWithLatestFromManyBenchmark {

    /**
     * Number of items emitted by the source Flowable.
     */
    @Param({ "1000", "10000" })
    public int sourceSize;

    /**
     * Number of "other" publishers combined with the source.
     */
    @Param({ "1", "2", "4", "8" })
    public int otherCount;

    private Flowable<Integer> source;

    private Publisher<?>[] others;

    private Function<Object[], Integer> combiner;

    @Setup(Level.Trial)
    public void setup() {
        // Simple source emitting a range of integers.
        source = Flowable.range(1, sourceSize);
        // Create the "other" publishers; each emits the same range synchronously.
        others = new Publisher<?>[otherCount];
        for (int i = 0; i < otherCount; i++) {
            others[i] = Flowable.range(1, sourceSize);
        }
        // Combiner that returns the source value (index 0) to keep work minimal.
        combiner = objects -> (Integer) objects[0];
    }

    /**
     * Benchmark method that subscribes to the operator and consumes all items.
     *
     * The subscription is performed using {@code blockingSubscribe} to ensure the
     * benchmark measures the complete processing of the stream.
     */
    @Benchmark
    public void withLatestFromMany(Blackhole bh) {
        // Apply the operator.
        Flowable<Integer> combined = new FlowableWithLatestFromMany<>(source, others, combiner);
        // Consume all items, feeding them into the Blackhole to prevent dead-code elimination.
        combined.blockingSubscribe(bh::consume);
    }
}

