/**
 * JMH benchmark for {@link SingleFlatMapObservable}.
 *
 * Measures the throughput of flattening a {@link Single} into an {@link Observable}
 * using the {@code flatMap} operator.
 *
 * The benchmark creates a fresh operator instance per invocation to include
 * allocation overhead, which is typical for library usage patterns.
 */
@BenchmarkMode(Mode.Throughput)
@OutputTimeUnit(TimeUnit.SECONDS)
@State(Scope.Thread)
@Warmup(iterations = 5, time = 1, timeUnit = TimeUnit.SECONDS)
@Measurement(iterations = 10, time = 1, timeUnit = TimeUnit.SECONDS)
@Fork(value = 2)
public class SingleFlatMapObservableBenchmark {

    /**
     * Source Single emitting a constant integer.
     */
    private SingleSource<Integer> source;

    /**
     * Mapper turning the integer into an Observable emitting the doubled value.
     */
    private Function<? super Integer, ? extends Observable<Integer>> mapper;

    @Setup(Level.Trial)
    public void setUp() {
        source = Single.just(1);
        mapper = i -> Observable.just(i * 2);
    }

    /**
     * Benchmark method that subscribes to the {@link SingleFlatMapObservable},
     * blocks until completion, and consumes the emitted items via {@link Blackhole}
     * to prevent dead‑code elimination.
     *
     * @param bh Blackhole to consume emitted values.
     */
    @Benchmark
    public void flatMapSingleToObservable(Blackhole bh) {
        new SingleFlatMapObservable<>(source, mapper).blockingSubscribe(bh::consume);
    }
}

