package io.reactivex.rxjava3.internal.operators.observable;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.TimeUnit;
import io.reactivex.rxjava3.annotations.*;
import io.reactivex.rxjava3.core.*;
import io.reactivex.rxjava3.disposables.*;
import io.reactivex.rxjava3.exceptions.*;
import io.reactivex.rxjava3.flowables.*;
import io.reactivex.rxjava3.functions.*;
import io.reactivex.rxjava3.internal.disposables.*;
import io.reactivex.rxjava3.internal.functions.*;
import io.reactivex.rxjava3.internal.fuseable.*;
import io.reactivex.rxjava3.internal.jdk8.*;
import io.reactivex.rxjava3.internal.observers.*;
import io.reactivex.rxjava3.internal.operators.completable.*;
import io.reactivex.rxjava3.internal.operators.flowable.*;
import io.reactivex.rxjava3.internal.operators.maybe.*;
import io.reactivex.rxjava3.internal.operators.mixed.*;
import io.reactivex.rxjava3.internal.operators.parallel.*;
import io.reactivex.rxjava3.internal.operators.single.*;
import io.reactivex.rxjava3.internal.queue.*;
import io.reactivex.rxjava3.internal.schedulers.*;
import io.reactivex.rxjava3.internal.subscribers.*;
import io.reactivex.rxjava3.internal.subscriptions.*;
import io.reactivex.rxjava3.internal.util.*;
import io.reactivex.rxjava3.observables.*;
import io.reactivex.rxjava3.observers.*;
import io.reactivex.rxjava3.operators.*;
import io.reactivex.rxjava3.parallel.*;
import io.reactivex.rxjava3.plugins.*;
import io.reactivex.rxjava3.processors.*;
import io.reactivex.rxjava3.schedulers.*;
import io.reactivex.rxjava3.subjects.*;
import io.reactivex.rxjava3.subscribers.*;
import org.openjdk.jmh.annotations.*;
import org.openjdk.jmh.infra.*;

/**
 * JMH benchmark for {@link io.reactivex.rxjava3.internal.operators.observable.ObservableBufferBoundary}.
 *
 * The benchmark measures the throughput (operations per second) of the bufferBoundary
 * operator when processing a configurable number of upstream items.
 *
 * Best practices applied:
 * - Use @State(Scope.Thread) to avoid sharing mutable state between threads.
 * - @Setup(Level.Trial) prepares the observable pipeline once per JVM fork.
 * - Blackhole consumes the downstream buffers to prevent dead‑code elimination.
 * - Warm‑up, measurement, and fork parameters are chosen to give stable results.
 */
@BenchmarkMode(Mode.Throughput)
@OutputTimeUnit(TimeUnit.SECONDS)
@Warmup(iterations = 5, time = 1, timeUnit = TimeUnit.SECONDS)
@Measurement(iterations = 10, time = 1, timeUnit = TimeUnit.SECONDS)
@Fork(value = 3, jvmArgsAppend = { "-XX:+UnlockDiagnosticVMOptions", "-XX:+PrintCompilation" })
@State(Scope.Thread)
public class ObservableBufferBoundaryBenchmark {

    /**
     * Number of items emitted by the upstream source.
     * Typical values are chosen to exercise both small‑ and medium‑sized streams.
     */
    @Param({ "1000", "10000", "100000" })
    public int size;

    /**
     * The observable that applies the bufferBoundary operator.
     * It is created once per trial to avoid measuring pipeline construction overhead.
     */
    private Observable<ArrayList<Integer>> bufferedObservable;

    /**
     * Set up the observable pipeline.
     *
     * The source emits a range of integers.
     * A single “open” signal starts a buffer, and the corresponding “close” signal
     * closes it immediately, resulting in one‑item buffers. This pattern stresses
     * the boundary handling logic without involving time‑based operators.
     */
    @Setup(Level.Trial)
    public void setUp() {
        Observable<Integer> source = Observable.range(1, size);
        // Open a buffer once; each open token will be closed immediately.
        ObservableSource<Object> open = Observable.just(new Object());
        // For each open token, return an Observable that emits a single item to close the buffer.
        Function<Object, ObservableSource<Object>> close = token -> Observable.just(new Object());
        // Buffer supplier creates a new mutable collection for each buffer.
        Supplier<ArrayList<Integer>> bufferSupplier = ArrayList::new;
        // Use the RxJava buffer operator with opening, closing, and supplier.
        bufferedObservable = source.buffer(open, close, bufferSupplier);
    }

    /**
     * Benchmark method that subscribes to the buffered observable and consumes all emitted buffers.
     *
     * @param bh Blackhole to consume the buffers and prevent dead‑code elimination.
     */
    @Benchmark
    public void bufferBoundaryThroughput(Blackhole bh) {
        // blockingSubscribe ensures the method returns only after the whole stream has been processed.
        bufferedObservable.blockingSubscribe(bh::consume);
    }
}

