import io.reactivex.rxjava3.internal.jdk8.*;
import io.reactivex.rxjava3.internal.observers.*;
import io.reactivex.rxjava3.internal.operators.completable.*;
import io.reactivex.rxjava3.internal.operators.flowable.*;
import io.reactivex.rxjava3.internal.operators.maybe.*;
import io.reactivex.rxjava3.internal.operators.mixed.*;
import io.reactivex.rxjava3.internal.operators.observable.*;
import io.reactivex.rxjava3.internal.operators.parallel.*;
import io.reactivex.rxjava3.internal.operators.single.*;
import io.reactivex.rxjava3.internal.queue.*;
import io.reactivex.rxjava3.internal.schedulers.*;
import io.reactivex.rxjava3.internal.subscribers.*;
import io.reactivex.rxjava3.internal.subscriptions.*;
import io.reactivex.rxjava3.internal.util.*;
import io.reactivex.rxjava3.observables.*;
import io.reactivex.rxjava3.observers.*;
import io.reactivex.rxjava3.operators.*;
import io.reactivex.rxjava3.parallel.*;
import io.reactivex.rxjava3.plugins.*;
import io.reactivex.rxjava3.processors.*;
import io.reactivex.rxjava3.schedulers.*;
import io.reactivex.rxjava3.subjects.*;
import io.reactivex.rxjava3.subscribers.*;
import org.openjdk.jmh.annotations.*;
import org.openjdk.jmh.infra.*;

/**
 * Benchmark for {@link ObservableCache}. The benchmark measures the throughput of
 * replaying a cached sequence to a new subscriber. The source sequence is a simple
 * range of integers; the cache is populated once during the @Setup phase.
 *
 * Best practices applied:
 * - Use @State(Scope.Benchmark) to share immutable data across iterations.
 * - Parameterize the size of the cached sequence to see scaling behavior.
 * - Warm‑up, measurement, and fork settings are provided to obtain stable results.
 * - The benchmark method does not allocate heavy objects inside the measured code
 *   (the TestObserver is created per invocation, which is negligible compared to
 *   the work of replaying the cached items).
 */
@BenchmarkMode(Mode.Throughput)
@OutputTimeUnit(TimeUnit.SECONDS)
@Warmup(iterations = 5, time = 1, timeUnit = TimeUnit.SECONDS)
@Measurement(iterations = 10, time = 1, timeUnit = TimeUnit.SECONDS)
@Fork(value = 2)
@State(Scope.Benchmark)
public class ObservableCacheBenchmark {

    /**
     * Number of items emitted by the source Observable and cached.
     * Typical values are chosen to cover small, medium and large caches.
     */
    @Param({ "1000", "10000", "100000" })
    public int size;

    /**
     * Source Observable that emits a range of integers.
     */
    private Observable<Integer> source;

    /**
     * The ObservableCache instance under test.
     */
    private ObservableCache<Integer> cache;

    /**
     * Populate the cache once before the measurement starts.
     * The {@code Observable.range} operator emits synchronously, so after subscription
     * the cache is already completed.
     */
    @Setup(Level.Trial)
    public void setUp() {
        source = Observable.range(0, size);
        cache = new ObservableCache<>(source, 128);
        // Subscribe a dummy observer to trigger the upstream subscription and fill the cache.
        cache.subscribe(new Observer<Integer>() {

            @Override
            public void onSubscribe(Disposable d) {
            }

            @Override
            public void onNext(Integer t) {
            }

            @Override
            public void onError(Throwable e) {
            }

            @Override
            public void onComplete() {
            }
        });
    }

    /**
     * Benchmark method that replays the cached sequence to a new subscriber.
     * The {@link TestObserver} waits until the sequence terminates, ensuring that
     * the whole replay path is exercised.
     */
    @Benchmark
    public void replayThroughput() throws Exception {
        TestObserver<Integer> testObserver = new TestObserver<>();
        cache.subscribe(testObserver);
        // Await completion; the timeout is generous to avoid false failures.
        testObserver.awaitDone(1, TimeUnit.MINUTES);
    }
}

