import org.openjdk.jmh.annotations.*;
import org.openjdk.jmh.infra.*;

/**
 * Benchmark for {@link io.reactivex.rxjava3.internal.operators.observable.ObservableFilter}.
 * Measures the throughput of the filter operator when applied to a hot stream of integers.
 *
 * The benchmark follows best practices:
 * - Uses @State(Scope.Thread) to avoid sharing mutable state between threads.
 * - Performs full subscription and consumption in each iteration to include all overhead.
 * - Utilises Blackhole to prevent dead‑code elimination.
 * - Configures warm‑up and measurement iterations.
 */
@BenchmarkMode(Mode.Throughput)
@OutputTimeUnit(TimeUnit.MILLISECONDS)
@Warmup(iterations = 5, time = 1, timeUnit = TimeUnit.SECONDS)
@Measurement(iterations = 10, time = 1, timeUnit = TimeUnit.SECONDS)
@Fork(2)
@Threads(1)
@State(Scope.Thread)
public class ObservableFilterBenchmark {

    /**
     * Number of items emitted by the source Observable per benchmark invocation.
     */
    @Param({ "1000", "10000", "100000" })
    public int size;

    /**
     * The source Observable emitting a range of integers.
     */
    private Observable<Integer> source;

    /**
     * Predicate used by the filter operator (keeps even numbers).
     */
    private Predicate<Integer> predicate;

    @Setup(Level.Trial)
    public void setUp() {
        // Create a cold Observable that emits a range of integers [1, size]
        source = Observable.range(1, size);
        // Simple predicate that filters out odd numbers
        predicate = i -> (i & 1) == 0;
    }

    /**
     * Benchmark method that subscribes to the filtered Observable and consumes all items.
     *
     * @param bh Blackhole to consume the emitted items and avoid dead‑code elimination.
     */
    @Benchmark
    public void filterAndConsume(Blackhole bh) {
        source.filter(predicate).subscribe(bh::consume);
    }
}

