/**
 * Benchmark for the {@code Observable.mergeWith(Completable)} operator,
 * which internally uses {@code ObservableMergeWithCompletable}.
 *
 * Measures throughput (operations per second) of merging a synchronous
 * {@link Observable} with a synchronous {@link Completable} and consuming
 * all items.
 */
@BenchmarkMode(Mode.Throughput)
@OutputTimeUnit(TimeUnit.SECONDS)
@Warmup(iterations = 5, time = 1, timeUnit = TimeUnit.SECONDS)
@Measurement(iterations = 10, time = 1, timeUnit = TimeUnit.SECONDS)
@Fork(value = 2)
@Threads(1)
public class ObservableMergeWithCompletableBenchmark {

    @State(Scope.Thread)
    public static class BenchmarkState {

        @Param({ "1000", "10000", "100000" })
        public int itemCount;

        Observable<Integer> source;

        Completable other;

        @Setup(Level.Trial)
        public void setUp() {
            source = Observable.range(1, itemCount);
            other = Completable.complete();
        }
    }

    @Benchmark
    public int mergeWithCompletable(BenchmarkState state) {
        // Use count() -> Single<Long> and block to get the result.
        return state.source.mergeWith(state.other).count().blockingGet().intValue();
    }
}

