/**
 * JMH benchmark for {@link ObservableReduceSeedSingle}.
 *
 * Measures the throughput of reducing an {@link Observable} with a seed value.
 * The benchmark uses a simple integer summation reducer, which is representative
 * of typical use‑cases and keeps the focus on the operator overhead.
 *
 * Best practices applied:
 * - @State(Scope.Thread) to avoid sharing mutable state between threads.
 * - @Param to vary the size of the source sequence.
 * - Warm‑up and measurement iterations to let the JIT stabilize.
 * - @Fork with a separate JVM for isolation.
 * - Blackhole consumption to prevent dead‑code elimination.
 */
@BenchmarkMode(Mode.Throughput)
@OutputTimeUnit(TimeUnit.SECONDS)
@Warmup(iterations = 5, time = 1, timeUnit = TimeUnit.SECONDS)
@Measurement(iterations = 10, time = 1, timeUnit = TimeUnit.SECONDS)
@Fork(value = 2, jvmArgsAppend = { "-XX:+UnlockDiagnosticVMOptions", "-XX:+PrintCompilation" })
@State(Scope.Thread)
public class ObservableReduceSeedSingleBenchmark {

    /**
     * Number of items emitted by the source Observable.
     * Typical values: 1 000, 10 000, 100 000.
     */
    @Param({ "1000", "10000", "100000" })
    public int size;

    private Observable<Integer> source;

    private BiFunction<Integer, Integer, Integer> sumReducer;

    private Integer seed;

    @Setup(Level.Trial)
    public void setUp() {
        // Create a cold Observable that emits a range of integers.
        source = Observable.range(1, size);
        // Simple sum reducer.
        sumReducer = (a, b) -> a + b;
        // Seed value for summation.
        seed = 0;
    }

    /**
     * Executes the reduce‑with‑seed operation and consumes the result.
     *
     * @param bh Blackhole to consume the final reduced value.
     */
    @Benchmark
    public void reduceWithSeed(Blackhole bh) {
        // Construct the operator directly to avoid extra operator chaining overhead.
        ObservableReduceSeedSingle<Integer, Integer> reduceSingle = new ObservableReduceSeedSingle<>(source, seed, sumReducer);
        // Subscribe and block to obtain the result. The blocking call is appropriate
        // for a micro‑benchmark because it forces the whole pipeline to execute.
        Single<Integer> single = reduceSingle;
        Integer result = single.blockingGet();
        // Consume the result to prevent dead‑code elimination.
        bh.consume(result);
    }
}

