        @Param({ "1000000" })
        public int itemCount;

        public ParallelFlowable<Integer> source;

        public Supplier<List<Integer>> collectionSupplier = () -> new ArrayList<>();

        public BiConsumer<List<Integer>, Integer> collector = (list, item) -> list.add(item);

        @Setup(Level.Trial)
