import org.openjdk.jmh.annotations.*;
import org.openjdk.jmh.infra.*;

/**
 * Benchmark for {@link ParallelFlatMapIterable}.
 *
 * The benchmark measures the throughput (items processed per second) of the
 * parallel flatMapIterable operator when applied to a simple range source.
 *
 * Best practices applied:
 * - Use @State(Scope.Benchmark) to share immutable data across iterations.
 * - Initialize heavy objects in @Setup(Level.Trial) to avoid measuring allocation cost.
 * - Use Blackhole to consume the emitted items and prevent dead‑code elimination.
 * - Configure warm‑up, measurement, forks and time units for reliable results.
 */
@BenchmarkMode(Mode.Throughput)
@OutputTimeUnit(TimeUnit.SECONDS)
@Warmup(iterations = 5, time = 1, timeUnit = TimeUnit.SECONDS)
@Measurement(iterations = 10, time = 1, timeUnit = TimeUnit.SECONDS)
@Fork(value = 2)
@Threads(1)
public class ParallelFlatMapIterableBenchmark {

    @State(Scope.Benchmark)
    public static class BenchmarkState {

        /**
         * Number of items emitted by the source per benchmark iteration.
         */
        @Param({ "1000", "10000", "100000" })
        public int itemCount;

        /**
         * Prefetch size for the operator (typical default is 32).
         */
        @Param({ "32" })
        public int prefetch;

        /**
         * Source ParallelFlowable emitting a range of integers.
         */
        ParallelFlowable<Integer> source;

        /**
         * Mapper converting each integer into a single‑element iterable.
         */
        Function<Integer, Iterable<Integer>> mapper;

        @Setup(Level.Trial)
        public void setUp() {
            // Create a parallel flowable that emits a contiguous range of integers.
            source = Flowable.range(1, itemCount).parallel();
            // Simple mapper that wraps each integer into a singleton iterable.
            mapper = i -> Collections.singletonList(i);
        }
    }

    @Benchmark
    public void flatMapIterable(BenchmarkState state, Blackhole bh) {
        // Apply the ParallelFlatMapIterable operator and consume all items.
        new ParallelFlatMapIterable<>(state.source, state.mapper, state.prefetch).// Convert back to a regular Flowable.
        sequential().blockingForEach(// Consume items using Blackhole.
        bh::consume);
    }
}

