@State(Scope.Benchmark)
public class ParallelReduceFullBenchmark {

    @Param({ "1", "2", "4", "8" })
    int parallelism;

    @Param({ "1000", "1000000" })
    int size;

    private ParallelReduceFull<Integer> operator;

    private static final BiFunction<Integer, Integer, Integer> REDUCER = (a, b) -> a + b;

    @Setup(Level.Trial)
    public void setUp() {
        ParallelFlowable<Integer> source = Flowable.range(1, size).parallel(parallelism).runOn(Schedulers.computation());
        operator = new ParallelReduceFull<>(source, REDUCER);
    }

    @Benchmark
    public void reduceFull(Blackhole bh) {
        Integer result = operator.blockingFirst();
        bh.consume(result);
    }
}

