 * element into a {@code Single} and then blocking to retrieve the value.
 *
 * Best practices applied:
 * - Use {@code @State(Scope.Thread)} to avoid sharing mutable state between threads.
 * - Perform heavy setup in {@code @Setup(Level.Trial)} to exclude it from the measurement.
 * - Use {@code blockingGet()} to ensure the subscription completes within the benchmark iteration.
 * - Configure warm‑up, measurement, and fork parameters to obtain stable results.
 */
@BenchmarkMode(Mode.Throughput)
@OutputTimeUnit(TimeUnit.MILLISECONDS)
@Warmup(iterations = 5, time = 1, timeUnit = TimeUnit.SECONDS)
@Measurement(iterations = 5, time = 1, timeUnit = TimeUnit.SECONDS)
@Fork(1)
public class SingleFromPublisherBenchmark {

    @State(Scope.Thread)
    public static class BenchmarkState {

        /**
         * Single that wraps a Publisher emitting exactly one integer.
         */
        Single<Integer> single;

        @Setup(Level.Trial)
        public void setUp() {
            Publisher<Integer> publisher = Flowable.just(1);
            single = new SingleFromPublisher<>(publisher);
        }
    }

    @Benchmark
    public Integer singleFromPublisherThroughput(BenchmarkState state) {
        // blockingGet() forces the subscription to complete, making the measurement deterministic.
        return state.single.blockingGet();
    }
}

