package io.reactivex.rxjava3.internal.schedulers;

import java.util.concurrent.*;
import io.reactivex.rxjava3.annotations.*;
import io.reactivex.rxjava3.core.*;
import io.reactivex.rxjava3.disposables.*;
import io.reactivex.rxjava3.exceptions.*;
import io.reactivex.rxjava3.flowables.*;
import io.reactivex.rxjava3.functions.*;
import io.reactivex.rxjava3.internal.disposables.*;
import io.reactivex.rxjava3.internal.functions.*;
import io.reactivex.rxjava3.internal.fuseable.*;
import io.reactivex.rxjava3.internal.jdk8.*;
import io.reactivex.rxjava3.internal.observers.*;
import io.reactivex.rxjava3.internal.operators.completable.*;
import io.reactivex.rxjava3.internal.operators.flowable.*;
import io.reactivex.rxjava3.internal.operators.maybe.*;
import io.reactivex.rxjava3.internal.operators.mixed.*;
import io.reactivex.rxjava3.internal.operators.observable.*;
import io.reactivex.rxjava3.internal.operators.parallel.*;
import io.reactivex.rxjava3.internal.operators.single.*;
import io.reactivex.rxjava3.internal.queue.*;
import io.reactivex.rxjava3.internal.subscribers.*;
import io.reactivex.rxjava3.internal.subscriptions.*;
import io.reactivex.rxjava3.internal.util.*;
import io.reactivex.rxjava3.observables.*;
import io.reactivex.rxjava3.observers.*;
import io.reactivex.rxjava3.operators.*;
import io.reactivex.rxjava3.parallel.*;
import io.reactivex.rxjava3.plugins.*;
import io.reactivex.rxjava3.processors.*;
import io.reactivex.rxjava3.schedulers.*;
import io.reactivex.rxjava3.subjects.*;
import io.reactivex.rxjava3.subscribers.*;
import org.openjdk.jmh.annotations.*;
import org.openjdk.jmh.infra.*;

/**
 * JMH microbenchmarks for {@link ScheduledRunnable}.
 *
 * The benchmarks focus on the most critical public methods:
 * <ul>
 *   <li>{@code run()}</li>
 *   <li>{@code dispose()}</li>
 *   <li>{@code setFuture(Future)}</li>
 * </ul>
 *
 * Each benchmark creates a fresh {@code ScheduledRunnable} instance to avoid state
 * contamination between iterations. A minimal {@link DisposableContainer}
 * implementation is used to satisfy the constructor contract without adding
 * overhead.
 *
 * Throughput mode is used because we are interested in the number of
 * operations per time unit that the class can sustain under typical usage.
 */
@BenchmarkMode(Mode.Throughput)
@OutputTimeUnit(TimeUnit.MILLISECONDS)
@Warmup(iterations = 5, time = 1, timeUnit = TimeUnit.SECONDS)
@Measurement(iterations = 10, time = 1, timeUnit = TimeUnit.SECONDS)
@Fork(value = 2, jvmArgsAppend = { "-XX:+UnlockDiagnosticVMOptions", "-XX:+PrintCompilation" })
@State(Scope.Thread)
public class ScheduledRunnableBenchmark {

    /**
     * Simple no‑op {@link DisposableContainer} implementation.
     *
     * Implements only the methods required by the current RxJava3 version.
     */
    static final class NoOpContainer implements DisposableContainer {

        public boolean add(Disposable d) {
            return true;
        }

        public boolean delete(Disposable d) {
            return true;
        }

        // Some RxJava versions expose a delete(Object) method; provide a stub.
        public boolean delete(Object o) {
            return true;
        }

        public boolean remove(Disposable d) {
            return true;
        }

        public boolean contains(Disposable d) {
            return false;
        }

        public int size() {
            return 0;
        }

        public boolean isDisposed() {
            return false;
        }

        public void dispose() {
            // no‑op
        }
    }

    /**
     * A trivial {@link Runnable} that does virtually nothing.
     */
    private static final Runnable NO_OP_RUNNABLE = () -> {
        // no‑op
    };

    /**
     * A completed {@link Future} used for {@code setFuture} benchmark.
     */
    private static final Future<?> COMPLETED_FUTURE = CompletableFuture.completedFuture(null);

    /**
     * State for the {@code run()} benchmark.
     */
    @State(Scope.Thread)
    public static class RunState {

        ScheduledRunnable sr;

        @Setup(Level.Invocation)
        public void setUp() {
            sr = new ScheduledRunnable(NO_OP_RUNNABLE, new NoOpContainer(), true);
        }
    }

    /**
     * State for the {@code dispose()} benchmark.
     */
    @State(Scope.Thread)
    public static class DisposeState {

        ScheduledRunnable sr;

        @Setup(Level.Invocation)
        public void setUp() {
            sr = new ScheduledRunnable(NO_OP_RUNNABLE, new NoOpContainer(), true);
            // Ensure the future slot is populated to exercise the cancel path.
            sr.setFuture(new CompletableFuture<>());
        }
    }

    /**
     * State for the {@code setFuture()} benchmark.
     */
    @State(Scope.Thread)
    public static class SetFutureState {

        ScheduledRunnable sr;

        @Setup(Level.Invocation)
        public void setUp() {
            sr = new ScheduledRunnable(NO_OP_RUNNABLE, new NoOpContainer(), true);
        }
    }

    @Benchmark
    public void run(RunState state, Blackhole bh) {
        state.sr.run();
        bh.consume(state.sr);
    }

    @Benchmark
    public void dispose(DisposeState state, Blackhole bh) {
        state.sr.dispose();
        bh.consume(state.sr);
    }

    @Benchmark
    public void setFuture(SetFutureState state, Blackhole bh) {
        state.sr.setFuture(COMPLETED_FUTURE);
        bh.consume(state.sr);
    }
}

