import io.reactivex.rxjava3.internal.operators.flowable.*;
import io.reactivex.rxjava3.internal.operators.maybe.*;
import io.reactivex.rxjava3.internal.operators.mixed.*;
import io.reactivex.rxjava3.internal.operators.observable.*;
import io.reactivex.rxjava3.internal.operators.parallel.*;
import io.reactivex.rxjava3.internal.operators.single.*;
import io.reactivex.rxjava3.internal.queue.*;
import io.reactivex.rxjava3.internal.schedulers.*;
import io.reactivex.rxjava3.internal.subscribers.*;
import io.reactivex.rxjava3.internal.subscriptions.*;
import io.reactivex.rxjava3.internal.util.*;
import io.reactivex.rxjava3.observables.*;
import io.reactivex.rxjava3.observers.*;
import io.reactivex.rxjava3.operators.*;
import io.reactivex.rxjava3.parallel.*;
import io.reactivex.rxjava3.plugins.*;
import io.reactivex.rxjava3.processors.*;
import io.reactivex.rxjava3.schedulers.*;
import io.reactivex.rxjava3.subjects.*;
import io.reactivex.rxjava3.subscribers.*;
import org.openjdk.jmh.annotations.*;
import org.openjdk.jmh.infra.*;

/**
 * JMH benchmarks for {@link TrampolineScheduler}.
 *
 * The benchmarks focus on the throughput of scheduling tasks
 * (both immediate and delayed) via the scheduler's direct API
 * and via a {@link Scheduler.Worker}. The workload of the scheduled
 * {@code Runnable} is intentionally trivial to isolate the overhead
 * of the scheduling mechanism itself.
 */
@BenchmarkMode(Mode.Throughput)
@OutputTimeUnit(TimeUnit.MILLISECONDS)
@Warmup(iterations = 5, time = 1, timeUnit = TimeUnit.SECONDS)
@Measurement(iterations = 10, time = 1, timeUnit = TimeUnit.SECONDS)
@Fork(value = 2)
@State(Scope.Benchmark)
public class TrampolineSchedulerBenchmark {

    /**
     * Scheduler instance under test.
     */
    private Scheduler scheduler;

    /**
     * Worker obtained from the scheduler (reused across iterations).
     */
    private Scheduler.Worker worker;

    /**
     * Simple runnable that does minimal work; the Blackhole prevents dead‑code elimination.
     */
    private Runnable blackholeRunnable;

    /**
     * Counter used inside the runnable to create a tiny side‑effect.
     */
    private AtomicInteger counter;

    @Setup(Level.Trial)
    public void setUp() {
        scheduler = TrampolineScheduler.instance();
        worker = scheduler.createWorker();
        counter = new AtomicInteger();
        blackholeRunnable = () -> counter.incrementAndGet();
    }

    @TearDown(Level.Trial)
    public void tearDown() {
        worker.dispose();
    }

    /* --------------------------------------------------------------------- */
    /* Direct scheduling benchmarks (no delay)                              */
    /* --------------------------------------------------------------------- */
    @Benchmark
    public Disposable scheduleDirectNoDelay(Blackhole bh) {
        Disposable d = scheduler.scheduleDirect(() -> bh.consume(counter.incrementAndGet()));
        // The returned Disposable is a no‑op (EmptyDisposable), but we return it
        // to keep the benchmark signature realistic.
        return d;
    }

    @Benchmark
    public Disposable scheduleDirectWithDelay(Blackhole bh) {
        // 1 µs delay – small enough to keep the benchmark fast while still exercising the delayed path.
        Disposable d = scheduler.scheduleDirect(() -> bh.consume(counter.incrementAndGet()), 1, TimeUnit.MICROSECONDS);
        return d;
    }

    /* --------------------------------------------------------------------- */
    /* Worker scheduling benchmarks (no delay)                              */
    /* --------------------------------------------------------------------- */
    @Benchmark
    public Disposable workerScheduleNoDelay(Blackhole bh) {
        Disposable d = worker.schedule(() -> bh.consume(counter.incrementAndGet()));
        return d;
    }

    @Benchmark
    public Disposable workerScheduleWithDelay(Blackhole bh) {
        // 1 µs delay – exercises the SleepingRunnable path without introducing noticeable wall‑clock latency.
        Disposable d = worker.schedule(() -> bh.consume(counter.incrementAndGet()), 1, TimeUnit.MICROSECONDS);
        return d;
    }

    /* --------------------------------------------------------------------- */
    /* Helper benchmark that repeatedly schedules a batch of tasks.         */
    /* This mimics a realistic usage pattern where many tasks are queued.   */
    /* --------------------------------------------------------------------- */
    @Benchmark
    public void scheduleBatchOfTasks(Blackhole bh) {
        // Schedule a small batch (e.g., 10 tasks) to amortize loop overhead.
        for (int i = 0; i < 10; i++) {
            worker.schedule(() -> bh.consume(counter.incrementAndGet()));
        }
    }
}

