import org.openjdk.jmh.infra.*;

@BenchmarkMode(Mode.Throughput)
@OutputTimeUnit(TimeUnit.MILLISECONDS)
@State(Scope.Thread)
@Warmup(iterations = 5, time = 1, timeUnit = TimeUnit.SECONDS)
@Measurement(iterations = 10, time = 1, timeUnit = TimeUnit.SECONDS)
@Fork(2)
public class QueueDrainHelperBenchmark {

    @Param({ "128", "1024", "8192" })
    public int size;

    private Queue<Integer> queue;

    private AtomicLong state;

    private Subscriber<Integer> subscriber;

    private BooleanSupplier notCancelled;

    @Setup(Level.Invocation)
    public void setUp() {
        queue = new ArrayDeque<>(size);
        for (int i = 0; i < size; i++) {
            queue.offer(i);
        }
        state = new AtomicLong(0L);
        subscriber = new Subscriber<Integer>() {

            @Override
            public void onSubscribe(Subscription s) {
                s.request(Long.MAX_VALUE);
            }

            @Override
            public void onNext(Integer integer) {
            }

            @Override
            public void onError(Throwable t) {
            }

            @Override
            public void onComplete() {
            }
        };
        notCancelled = () -> false;
    }

    @Benchmark
    public boolean benchmarkPostCompleteRequest() {
        return QueueDrainHelper.postCompleteRequest(1L, subscriber, queue, state, notCancelled);
    }

    @Benchmark
    public boolean benchmarkPostCompleteDrain() {
        long requested = ((long) size) & QueueDrainHelper.REQUESTED_MASK;
        state.set(requested);
        return QueueDrainHelper.postCompleteDrain(state.get(), subscriber, queue, state, notCancelled);
    }
}

